(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.012+t*0.15)*8+Math.cos(sx*0.008-t*0.1)*6;
  const w2y = Math.cos(sx*0.014-t*0.12)*8+Math.sin(sy*0.01+t*0.18)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.4],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.2],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1,0.6],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+1)*40,0.085,1.8,1.3]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    mS+=Math.sin(d*f*0.5-t*sp*0.4+2.5+ph*0.7)*0.6;
  }
  const n=src.length,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    +Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2
    +Math.sin(fx*0.06+fy*0.08-t*1.8)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03+ang*6-t*0.8)*0.2;
  const weave=Math.sin(fx*0.18)*Math.sin(fy*0.18)+Math.sin((fx*0.7+fy*1.3)*0.08+t*0.6)*0.4
    +Math.sin((fx*1.1-fy*0.9)*0.07-t*0.9)*0.3;
  const reaction=Math.tanh((act-inh*0.6+bg*0.25+spiral*0.3+mod*0.15+weave*0.1)*2.0);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5+weave*0.3)*1.5)*0.25;
  const pulse=0.9+Math.sin(t*0.4)*0.1;
  const blend=(reaction*0.65+cell*0.2+mod*0.15)*pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,35,85],[18,72,108],[25,118,128],[45,155,140],
    [120,185,120],[195,195,75],[220,165,55],[215,120,65],[185,72,72],
    [145,45,85],[95,25,72],[50,18,58],[5,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12+Math.sin(t*2)*0.03:1.0;
  const glow=1.0+Math.max(0,reaction-0.3)*0.15;
  const finalMul=lum*edge*glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*finalMul)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*finalMul)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*finalMul)|0
  ];
}
